    private WatchdogServiceOptions options(boolean enabled, String device, boolean failOnUnavailableDevice,
            int pingInterval) {
        final Map<String, Object> properties = new HashMap<>();
        properties.put("enabled", enabled);
        properties.put("watchdogMode", "direct");
        properties.put("watchdogDevice", device);
        properties.put("failOnUnavailableDevice", failOnUnavailableDevice);
        properties.put("pingInterval", pingInterval);
        return new WatchdogServiceOptions(properties);
    }

    private static class TestDirectBackend extends DirectWatchdogBackend {

        private final Map<String, RecordingWatchdogDevice> devices = new HashMap<>();
        private final List<String> openedDevices = new ArrayList<>();
        private final List<String> rebootCauses = new ArrayList<>();
        private boolean deviceExists = true;
        private boolean openFails;
        private int timeoutSeconds;
        private long gracePeriodMs = LONG_PERIOD_MS;
        private long rebootRetryIntervalMs = LONG_PERIOD_MS;
        private int failingReboots;
        private int rebootRequests;

        @Override
        protected WatchdogDevice createWatchdogDevice(String watchdogDevice) throws IOException {
            if (this.openFails) {
                throw new IOException("Device or resource busy");
            }
            this.openedDevices.add(watchdogDevice);
            final RecordingWatchdogDevice device = new RecordingWatchdogDevice(this.timeoutSeconds);
            this.devices.put(watchdogDevice, device);
            return device;
        }

        @Override
        protected boolean isWatchdogDeviceAvailable(String watchdogDevice) {
            return this.deviceExists;
        }

        @Override
        protected void stopWatchdogd() {
            // do not run system commands in tests
        }

        @Override
        protected void writeRebootCause(WatchdogServiceOptions options, String rebootCause) {
            this.rebootCauses.add(rebootCause);
        }

        @Override
        protected void rebootSystem() throws KuraException {
            this.rebootRequests++;
            if (this.rebootRequests <= this.failingReboots) {
                throw new KuraException(KuraErrorCode.OS_COMMAND_ERROR, "reboot", 1);
            }
        }

        @Override
        protected long getGracePeriod() {
            return this.gracePeriodMs;
        }

        @Override
        protected long getRebootRetryInterval() {
            return this.rebootRetryIntervalMs;
        }
    }
